{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses ReadItem for single-partition queries
        // and requires sync methods to be explicitly enabled.
        // Also, raw SQL using `c.Discriminator` must change to `c["$type"]`
        // unless HasJsonPropertyName("Discriminator") is configured (done above).
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

